const r = await tools.job_output({ job_id: "pwsh-63b80c871a4f4652", wait: true, timeout_ms: 280000 });
const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const files = ["_b_xianyu_search.html","_b_xiaohongshu_search.html","_b_bilibili_search.html","_b_nowcoder.html","_b_zhihu_search.html"];
const res = [];
for (const f of files) {
  try {
    const h = await fs.readFile(S+"\\"+f,"utf8");
    const text = h.replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim();
    const stu = (text.match(/(学生|大学生|论文|考研|作业|教材|笔记|家教|简历)/g)||[]).length;
    const money = (text.match(/[¥￥]\s?[0-9,]+|\d+\s*元/g)||[]).length;
    res.push({ f: f.replace("_b_","").replace(".html",""), kb: Math.round(h.length/1024), textLen: text.length, stu, money, head: text.slice(0,150) });
  } catch { res.push({ f, err:"missing" }); }
}
return { status: r.job.status, res };
